import {
  bigint,
  boolean,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

// ---------------------------------------------------------------------------
// paysim-bd domain model (Phase 0). Conventions:
// - ids are uuids generated by Postgres (gen_random_uuid, built-in since PG13)
// - code uses camelCase, columns are snake_case
// - request/response bodies live inline up to 16 KB, above that in object
//   storage with only the key stored here (see body-store.ts)
// - every state change writes an `events` row (enforced by later phases)
// ---------------------------------------------------------------------------

const createdAt = () =>
  timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow();

const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true, mode: 'date' })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

/** Isolation unit. One default row locally; anonymous keys when hosted. */
export const workspaces = pgTable('workspaces', {
  id: uuid('id').primaryKey().defaultRandom(),
  key: text('key').notNull().unique(),
  name: text('name').notNull(),
  createdAt: createdAt(),
});
export type Workspace = typeof workspaces.$inferSelect;

/**
 * Declarative callback/timing scripts (zod-validated in Phase 2).
 * `workspaceId = null` marks a built-in preset shared by all workspaces.
 */
export const scenarios = pgTable('scenarios', {
  id: uuid('id').primaryKey().defaultRandom(),
  workspaceId: uuid('workspace_id').references(() => workspaces.id, { onDelete: 'cascade' }),
  gateway: text('gateway').notNull(),
  name: text('name').notNull(),
  definition: jsonb('definition').$type<Record<string, unknown>>().notNull().default({}),
  isDefault: boolean('is_default').notNull().default(false),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});
export type Scenario = typeof scenarios.$inferSelect;

/** A merchant's sandbox app inside a gateway. Credentials are ALWAYS fake. */
export const gatewayApps = pgTable('gateway_apps', {
  id: uuid('id').primaryKey().defaultRandom(),
  workspaceId: uuid('workspace_id')
    .notNull()
    .references(() => workspaces.id, { onDelete: 'cascade' }),
  gateway: text('gateway').notNull(),
  name: text('name').notNull(),
  credentials: jsonb('credentials').$type<Record<string, unknown>>().notNull().default({}),
  defaultScenarioId: uuid('default_scenario_id').references(() => scenarios.id, {
    onDelete: 'set null',
  }),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});
export type GatewayApp = typeof gatewayApps.$inferSelect;

/**
 * One simulated payment. `state` follows the per-gateway state machine
 * (Phase 1+). Money is stored in minor units (poisha for BDT).
 */
export const transactions = pgTable(
  'transactions',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    gatewayAppId: uuid('gateway_app_id')
      .notNull()
      .references(() => gatewayApps.id, { onDelete: 'cascade' }),
    gateway: text('gateway').notNull(),
    state: text('state').notNull(),
    /** Gateway-side reference (e.g. SSLCommerz tran_id). */
    gatewayTxnId: text('gateway_txn_id'),
    /** Checkout session reference (e.g. SSLCommerz sessionkey). */
    gatewaySessionKey: text('gateway_session_key'),
    amountMinor: integer('amount_minor').notNull(),
    currency: text('currency').notNull().default('BDT'),
    customer: jsonb('customer').$type<Record<string, unknown>>().notNull().default({}),
    /** Gateway-specific fields owned by the plugin state machine. */
    metadata: jsonb('metadata').$type<Record<string, unknown>>().notNull().default({}),
    scenarioOverrideId: uuid('scenario_override_id').references(() => scenarios.id, {
      onDelete: 'set null',
    }),
    idempotencyKey: text('idempotency_key'),
    expiresAt: timestamp('expires_at', { withTimezone: true, mode: 'date' }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    // NULL gatewayTxnIds never collide (Postgres treats NULLs as distinct).
    uniqueIndex('transactions_gateway_ref_unique').on(t.gateway, t.gatewayTxnId),
    uniqueIndex('transactions_gateway_session_unique').on(t.gateway, t.gatewaySessionKey),
    index('transactions_workspace_list_idx').on(t.workspaceId, t.createdAt),
  ],
);
export type Transaction = typeof transactions.$inferSelect;

/** Append-only timeline. Writers insert; nothing updates or deletes. */
export const events = pgTable(
  'events',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    transactionId: uuid('transaction_id')
      .notNull()
      .references(() => transactions.id, { onDelete: 'cascade' }),
    type: text('type').notNull(),
    data: jsonb('data').$type<Record<string, unknown>>().notNull().default({}),
    createdAt: createdAt(),
  },
  (t) => [index('events_transaction_timeline_idx').on(t.transactionId, t.createdAt)],
);
export type Event = typeof events.$inferSelect;

/**
 * One row per outbound callback attempt (IPN/webhook). `scheduledFor` in the
 * future means "honour the scenario delay / backoff"; the Phase 2 scheduler
 * polls only while such rows exist so Neon can scale to zero.
 */
export const callbackDeliveries = pgTable(
  'callback_deliveries',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    transactionId: uuid('transaction_id')
      .notNull()
      .references(() => transactions.id, { onDelete: 'cascade' }),
    kind: text('kind').notNull(),
    targetUrl: text('target_url').notNull(),
    attemptNo: integer('attempt_no').notNull().default(1),
    status: text('status').notNull(),
    latencyMs: integer('latency_ms'),
    requestBody: text('request_body'),
    requestBodyKey: text('request_body_key'),
    responseStatus: integer('response_status'),
    responseSnippet: text('response_snippet'),
    responseBodyKey: text('response_body_key'),
    scheduledFor: timestamp('scheduled_for', { withTimezone: true, mode: 'date' })
      .notNull()
      .defaultNow(),
    sentAt: timestamp('sent_at', { withTimezone: true, mode: 'date' }),
    createdAt: createdAt(),
  },
  (t) => [
    index('callback_deliveries_transaction_idx').on(t.transactionId),
    index('callback_deliveries_schedule_idx').on(t.status, t.scheduledFor),
  ],
);
export type CallbackDelivery = typeof callbackDeliveries.$inferSelect;

/**
 * Persisted scheduled jobs (Phase 2): scenario steps, session expiry,
 * delivery retries. The scheduler arms ONE in-process
 * timer for the earliest pending row and disarms when none remain, so an
 * idle Neon database still scales to zero. Anything overdue runs on boot.
 */
export const jobs = pgTable(
  'jobs',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    transactionId: uuid('transaction_id').references(() => transactions.id, {
      onDelete: 'cascade',
    }),
    /** scenario-step | session-expiry | delivery-retry */
    type: text('type').notNull(),
    payload: jsonb('payload').$type<Record<string, unknown>>().notNull().default({}),
    runAt: timestamp('run_at', { withTimezone: true, mode: 'date' }).notNull(),
    /** pending | running | done | failed | cancelled */
    status: text('status').notNull().default('pending'),
    attempts: integer('attempts').notNull().default(0),
    lastError: text('last_error'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('jobs_due_idx').on(t.status, t.runAt),
    index('jobs_transaction_idx').on(t.transactionId),
  ],
);
export type Job = typeof jobs.$inferSelect;

/** Per-workspace fake-clock offset in milliseconds (Phase 2). */
export const clockState = pgTable('clock_state', {
  workspaceId: uuid('workspace_id')
    .primaryKey()
    .references(() => workspaces.id, { onDelete: 'cascade' }),
  offsetMs: bigint('offset_ms', { mode: 'number' }).notNull().default(0),
  updatedAt: updatedAt(),
});
export type ClockState = typeof clockState.$inferSelect;

/** Recorded real-sandbox fixtures for the Phase 5 parity suite. */
export const recordings = pgTable('recordings', {
  id: uuid('id').primaryKey().defaultRandom(),
  workspaceId: uuid('workspace_id')
    .notNull()
    .references(() => workspaces.id, { onDelete: 'cascade' }),
  gateway: text('gateway').notNull(),
  name: text('name'),
  objectKey: text('object_key').notNull(),
  metadata: jsonb('metadata').$type<Record<string, unknown>>().notNull().default({}),
  sizeBytes: integer('size_bytes').notNull().default(0),
  createdAt: createdAt(),
});
export type Recording = typeof recordings.$inferSelect;

/**
 * Small cross-instance key/value state for plugins (e.g. bKash auth
 * tokens), so serverless instances share it. Rows past expires_at are
 * ignored on read and pruned opportunistically.
 */
export const kvEntries = pgTable(
  'kv_entries',
  {
    namespace: text('namespace').notNull(),
    key: text('key').notNull(),
    value: jsonb('value').$type<Record<string, unknown>>().notNull(),
    expiresAt: timestamp('expires_at', { withTimezone: true, mode: 'date' }).notNull(),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex('kv_entries_ns_key_idx').on(t.namespace, t.key)],
);
export type KvEntry = typeof kvEntries.$inferSelect;
